import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Sparkles, Loader2, RefreshCw, Download } from 'lucide-react';
import { base44 } from '@/api/base44Client';
import { cn } from "@/lib/utils";

export default function TraceReflection({ belief, onSave }) {
  const [isLoading, setIsLoading] = useState(false);
  const [reflection, setReflection] = useState(null);
  const [error, setError] = useState(null);

  const generateReflection = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 30000); // 30 second timeout

      const response = await fetch('http://localhost:3002/api/generate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: 'llama3.2:3b',
          prompt: `When responding to a users belief entry, follow these rules strictly:

Write in natural paragraph form only.

Do not use bullet points.
Do not use numbered lists.
Do not use emojis.
Do not use special characters.
Do not use bold, italics, or formatting.
Do not repeat the users question.
Do not restate the belief verbatim.
Do not summarize mechanically.

Do not begin with phrases like It sounds like, You seem to be saying, or similar filler language.

Your tone must be calm, neutral, curious, respectful, and intellectually honest. The response should feel like it was written by a thoughtful person sitting beside the user, not by an AI system.

You may gently highlight an assumption, notice tension or uncertainty, reflect on possible implications, or ask at most one subtle reflective question. If you ask a question, it should feel natural and not interrogative.

You must not give direct advice, tell the user what to do, moralize, persuade, validate excessively, or sound clinical.

Keep responses between 4 and 8 sentences. Vary sentence length naturally. Avoid rigid structure.

The goal is to help the user see their own thinking more clearly, not to change their mind.

Always prioritize clarity, depth, and humanity over efficiency.

The user has recorded this belief:

BELIEF: "${belief.statement}"

WHY THEY BELIEVE IT: "${belief.reasoning || 'Not specified'}"

EVIDENCE/EXPERIENCES: "${belief.evidence || 'Not specified'}"

CONFIDENCE LEVEL: ${belief.confidence}/10

WHAT WOULD CHANGE THEIR MIND: "${belief.what_would_change || 'Not specified'}"

Please provide a thoughtful reflection following all the rules above.`,
          stream: false
        }),
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      setReflection(data);
    } catch (err) {
      if (err.name === 'AbortError') {
        setError("Request timed out. Please try again.");
      } else {
        setError("Couldn't generate reflection. You can try again later.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!reflection) return;

    console.log('Trace Reflection: Starting save process');
    console.log('Current belief:', belief);
    console.log('New reflection:', reflection);

    const newTraceReflection = {
      date: new Date().toISOString(),
      content: JSON.stringify(reflection)
    };

    console.log('New Trace reflection object:', newTraceReflection);

    const existingReflections = belief.ai_reflections || [];
    console.log('Existing reflections:', existingReflections);

    await onSave({
      ai_reflections: [...existingReflections, newTraceReflection]
    });

    console.log('Trace Reflection: Save completed');
  };

  const handleExport = () => {
    if (!reflection) return;

    console.log('Trace Reflection: Starting export process');

    // Create thinking report content
    const reportContent = `Trace Thinking Report
Generated: ${new Date().toLocaleString()}

Belief: "${belief.statement}"
Confidence: ${belief.confidence}/10

Reasoning: ${belief.reasoning || 'Not specified'}

Evidence: ${belief.evidence || 'Not specified'}

What would change mind: ${belief.what_would_change || 'Not specified'}

Trace Reflection:
${reflection.summary || 'No reflection available'}

Questions to consider:
${reflection.clarifying_questions?.join('\n') || 'No questions available'}

Possible assumptions:
${reflection.assumptions_noticed || 'No assumptions identified'}

---
Report generated by Trace App
`;

    // Create and download file
    const blob = new Blob([reportContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `trace-thinking-report-${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    console.log('Trace Reflection: Export completed');
  };

  if (!reflection && !isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
            <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
          </div>
          <div className="flex-1">
            <h3 className="font-medium text-slate-800 mb-1">Trace Reflection</h3>
            <p className="text-sm text-slate-600 mb-4">
              Get a gentle reflection to help clarify your thinking. The Trace won't judge or try to change your mind.
            </p>
            <Button
              onClick={generateReflection}
              disabled={isLoading}
              className="bg-white hover:bg-slate-50 text-[#5C6B5E] border border-[#5C6B5E]/20 rounded-xl"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              Reflect with Trace
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-center justify-center gap-3 py-8">
          <Loader2 className="w-5 h-5 animate-spin text-[#5C6B5E]" />
          <span className="text-slate-600">Thinking gently...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 rounded-2xl p-6">
        <p className="text-red-600 text-sm mb-3">{error}</p>
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-red-600 border-red-200"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Try again
        </Button>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6 space-y-4">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-[#5C6B5E]" />
        <span className="text-sm font-medium text-[#5C6B5E]">AI Reflection</span>
      </div>

      {/* Summary */}
      {reflection.summary && (
        <div>
          <p className="text-sm text-slate-500 mb-1">In other words:</p>
          <p className="text-slate-700 leading-relaxed">{reflection.summary}</p>
        </div>
      )}

      {/* Questions */}
      {reflection.clarifying_questions?.length > 0 && (
        <div>
          <p className="text-sm text-slate-500 mb-2">Questions to consider:</p>
          <ul className="space-y-2">
            {reflection.clarifying_questions.map((q, i) => (
              <li key={i} className="flex gap-2 text-slate-700">
                <span className="text-[#5C6B5E]">•</span>
                <span className="leading-relaxed">{q}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Assumptions */}
      {reflection.assumptions_noticed && (
        <div>
          <p className="text-sm text-slate-500 mb-1">Possible assumptions:</p>
          <p className="text-slate-700 leading-relaxed">{reflection.assumptions_noticed}</p>
        </div>
      )}

      <div className="flex gap-2 pt-2">
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-slate-600 border-slate-200 rounded-lg"
        >
          <RefreshCw className="w-4 h-4 mr-1" />
          New reflection
        </Button>
        <Button
          onClick={handleSave}
          size="sm"
          className="bg-[#5C6B5E] hover:bg-[#4a574c] text-white rounded-lg"
        >
          Save this
        </Button>
        <Button
          onClick={handleExport}
          variant="outline"
          size="sm"
          className="text-slate-600 border-slate-200 rounded-lg"
        >
          <Download className="w-4 h-4 mr-1" />
          Export
        </Button>
      </div>
    </div>
  );
}
